def local_modules(entry):
    """The scripts/ modules a set of entry scripts import, transitively."""
    seen, todo = set(), list(entry)
    while todo:
        name = todo.pop()
        path = f"scripts/{name}.py"
        if name in seen or not os.path.exists(path):
            continue
        seen.add(name)
        tree = ast.parse(open(path, encoding="utf-8").read())
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                todo += [a.name.split(".")[0] for a in node.names]
            elif isinstance(node, ast.ImportFrom) and node.module:
                todo.append(node.module.split(".")[0])
    return sorted(f"scripts/{n}.py" for n in seen)


