def sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for block in iter(lambda: f.read(1 << 20), b""):
            h.update(block)
    return h.hexdigest()


# directories hashed as one digest each (too many files to list): the TTS cache (re-rendering for the offset check and
# the noise analysis reads it) and the six audio examples of every Gemini prompt (amendment 13.2, review C-M9)
TREES = ("data/p1/tts_cache", "data/p1v4/render/train_d00")


def tree_digest(root):
    """sha256 over the sorted (relative path, file sha256) pairs of every file under root, and the file count."""
    h, n = hashlib.sha256(), 0
    for dirpath, _, names in sorted(os.walk(root)):
        for name in sorted(names):
            p = os.path.join(dirpath, name)
            h.update(f"{os.path.relpath(p, root).replace(os.sep, '/')}\t{sha256(p)}\n".encode("utf-8"))
            n += 1
    return {"sha256": h.hexdigest(), "n_files": n}


