def nulls(x, path=""):
    """Open items: null values in a dict whose note says "to fill" (a null elsewhere is a real setting, e.g. B1's
    sentence-embedding cut "off")."""
    if isinstance(x, dict):
        here = [f"{path}/{k}" for k, v in x.items() if v is None and str(x.get("note", "")).startswith("to fill")]
        return here + [p for k, v in x.items() if isinstance(v, (dict, list)) for p in nulls(v, f"{path}/{k}")]
    if isinstance(x, list):
        return [p for i, v in enumerate(x) for p in nulls(v, f"{path}/{i}")]
    return []


# ------------------------------------------------------------------------------------------------ make, check

def versions():
    """Software and GPU of the freeze (review C-minor 10: thresholds were chosen on this machine's numerics)."""
    out = {"python": sys.version.split()[0]}
    for m in ("numpy", "scipy", "torch", "transformers", "sklearn"):
        try:
            out[m] = __import__(m).__version__
        except Exception as e:                               # noqa: BLE001 - recorded, not fatal
            out[m] = f"unavailable ({type(e).__name__})"
    try:
        import torch
        out["cuda_device"] = torch.cuda.get_device_name(0) if torch.cuda.is_available() else None
        out["cuda"] = torch.version.cuda
    except Exception as e:                                   # noqa: BLE001
        out["cuda_device"] = f"unavailable ({type(e).__name__})"
    return out


def git_clean():
    return subprocess.run(["git", "status", "--porcelain", "--untracked-files=no"], capture_output=True,
                          text=True).stdout.strip() == ""


def make(out=REHEARSAL):
    final = os.path.abspath(out) == os.path.abspath(D.FREEZE)
    if final and os.path.exists(out):                        # amendment 13.2: the final record is never overwritten
        raise SystemExit(f"{out} exists: change it only with `amend` (amendment 13.2)")
    if final and not git_clean():
        raise SystemExit("the working tree has uncommitted changes: commit them before the final record")
    files, missing = file_list()
    if missing:
        raise SystemExit(f"missing files: {missing}")
    st = settings()
    todo = nulls(st)
    if final and todo:
        raise SystemExit(f"the final freeze record cannot have open items: {todo}")
    t0 = time.time()
    rec = {"kind": "final" if final else "rehearsal",
           "made": time.strftime("%Y-%m-%d %H:%M:%S"),
           "git_commit": subprocess.run(["git", "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip(),
           "git_clean": git_clean(), "versions": versions(),
           "open_items": todo, "settings": st,
           "files": {f: {"sha256": sha256(f), "bytes": os.path.getsize(f)} for f in files},
           "trees": {t: tree_digest(t) for t in TREES}, "amendments": []}
    json.dump(rec, open(out, "w"), indent=1)
    print(f"wrote {out}: {len(files)} files ({sum(v['bytes'] for v in rec['files'].values()) / 1e9:.2f} GB) and "
          f"{len(TREES)} trees ({sum(v['n_files'] for v in rec['trees'].values())} files) in {time.time() - t0:.0f} s; "
          f"open items {len(todo)}; git clean {rec['git_clean']}")


def check(path=D.FREEZE, quiet=False):
    rec = json.load(open(path))
    bad = []
    for f, v in rec["files"].items():
        if not os.path.exists(f):
            bad.append((f, "missing"))
        elif os.path.getsize(f) != v["bytes"] or sha256(f) != v["sha256"]:
            bad.append((f, "changed"))
    for t, v in rec.get("trees", {}).items():
        if not os.path.isdir(t):
            bad.append((t, "missing"))
        elif tree_digest(t) != v:
            bad.append((t, "changed"))
    if not quiet:
        print(f"{path}: {len(rec['files'])} files and {len(rec.get('trees', {}))} trees, {len(bad)} missing or changed")
        for f, why in bad[:20]:
            print(f"  {why}: {f}")
    return bad


def amend(path, names, reason):
    """Amendment 13.2: after a bug fix on test day, re-hash only the named files (scripts that changed), assert that
    the frozen settings are unchanged, and append the old and new hashes; nothing else of the record changes."""
    if not reason:
        raise SystemExit("amend needs --reason")
    if not git_clean():
        raise SystemExit("commit the fix first: the working tree has uncommitted changes")
    rec = json.load(open(path))
    new_st = settings()
    if json.dumps(new_st, sort_keys=True, default=str) != json.dumps(rec["settings"], sort_keys=True, default=str):
        raise SystemExit("the frozen settings would change: an amendment may only re-hash fixed files")
    entry = {"time": time.strftime("%Y-%m-%d %H:%M:%S"), "reason": reason,
             "git_commit": subprocess.run(["git", "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip(),
             "files": {}}
    for f in names:
        f = f.replace("\\", "/")
        if f not in rec["files"]:
            raise SystemExit(f"{f} is not in the record (amend only re-hashes recorded files)")
        new = {"sha256": sha256(f), "bytes": os.path.getsize(f)}
        entry["files"][f] = {"old": rec["files"][f], "new": new}
        rec["files"][f] = new
    rec.setdefault("amendments", []).append(entry)
    json.dump(rec, open(path, "w"), indent=1)
    print(json.dumps(entry, indent=1))


_VERIFIED = {}


def verify_or_stop(path=D.FREEZE):
    """For the final scripts: stop before opening anything if the freeze record does not match the files (checked once
    per process: the tree digests read about 80,000 files)."""
    if path not in _VERIFIED:
        bad = check(path, quiet=True)
        if bad:
            raise SystemExit(f"freeze record mismatch ({len(bad)} files), first: {bad[:3]}")
        _VERIFIED[path] = json.load(open(path))
    return _VERIFIED[path]


if __name__ == "__main__":
    if sys.argv[1] == "make":
        make(sys.argv[2] if len(sys.argv) > 2 else REHEARSAL)
    elif sys.argv[1] == "check":
        sys.exit(1 if check(sys.argv[2] if len(sys.argv) > 2 else D.FREEZE) else 0)
    elif sys.argv[1] == "amend":
        a = sys.argv[2:]
        why = a[a.index("--reason") + 1] if "--reason" in a else None
        files = [x for i, x in enumerate(a) if x != "--reason" and (i == 0 or a[i - 1] != "--reason")]
        amend(D.FREEZE, files, why)
    else:
        raise SystemExit(__doc__)
